<template>
  <DraggableFormDialog :model-value="modelValue" class="business-finance-ledger" width="min(1450px, calc(100vw - 32px))" top="4vh" append-to-body @update:model-value="emit('update:modelValue',$event)">
    <template #header><DialogFieldSearchHeader ref="fieldSearchRef" v-model="fieldSearchKeyword" :title="label+'查账追账'" :fetch-suggestions="fetchFieldSuggestions" @select="locateDialogField" @clear="clearFieldSearch" /></template>
    <div ref="body" v-loading="loading"><el-alert v-if="error" type="error" :title="error" :closable="false" />
      <el-tabs v-model="tab"><el-tab-pane label="查账" name="audit" /><el-tab-pane label="追账" name="collection" /></el-tabs>
      <AppForm :model="filters" inline data-auto-draft="off"><el-form-item label="月份"><el-date-picker v-model="filters.months" type="months" value-format="YYYY-MM" clearable /></el-form-item><el-form-item label="客户／项目"><el-input v-model="filters.keyword" clearable placeholder="多关键词搜索" /></el-form-item><el-form-item label="检查条件"><el-select v-model="filters.issue" clearable style="width:220px"><el-option v-for="row in issues" :key="row.value" v-bind="row" /></el-select></el-form-item><el-form-item label="结算模式"><el-select v-model="filters.mode" clearable><el-option v-for="(text,key) in modes" :key="key" :value="key" :label="text" /></el-select></el-form-item></AppForm>
      <p>项目金额按财务确定的计费口径统计；不同货币分别小计。点击项目或客户查看项目明细。</p>
      <el-table :data="groups" border max-height="560"><el-table-column label="客户" min-width="160"><template #default="{row}"><el-button link @click="detail=visible.filter(item=>item.client_id===row.client_id)">{{row.client_name}}</el-button></template></el-table-column><el-table-column label="对账单／多单合并／项目" min-width="240"><template #default="{row}"><el-button link @click="detail=row.items">{{row.name}}</el-button></template></el-table-column><el-table-column label="结算模式" width="140"><template #default="{row}">{{modes[row.mode]}}</template></el-table-column><el-table-column label="项目金额" min-width="160"><template #default="{row}">{{money(sum(row.items,'billing_totals'))}}</template></el-table-column><el-table-column label="客户实际付款（累计）" min-width="180"><template #default="{row}">{{money(sum(row.items,'received_totals'))}}</template></el-table-column><el-table-column label="实付－应付差异" min-width="170"><template #default="{row}">{{money(sum(row.items,'payment_difference'))}}</template></el-table-column><el-table-column label="发票情况" min-width="150"><template #default="{row}">{{row.items.filter(item=>item.payload.settlement.invoice_required).length}} 个需发票；{{row.items.filter(item=>item.payload.invoice?.invoice_status==='issued').length}} 个已开</template></el-table-column><el-table-column label="毛利率" width="95"><template #default>待开发</template></el-table-column></el-table>
      <p>项目金额小计：{{money(sum(visible,'billing_totals'))}}；实际付款小计：{{money(sum(visible,'received_totals'))}}；差异小计：{{money(sum(visible,'payment_difference'))}}</p>
    </div><template #footer><el-button @click="load">重新加载</el-button><el-button @click="emit('update:modelValue',false)">关闭</el-button></template>
  </DraggableFormDialog>
  <DraggableFormDialog :model-value="!!detail" title="客户／结算项目明细" width="min(1100px, calc(100vw - 32px))" append-to-body @update:model-value="detail=null"><el-table :data="detail||[]" border max-height="500"><el-table-column prop="order_no" label="订单号" min-width="160" /><el-table-column prop="project_name" label="项目名称" min-width="250" /><el-table-column prop="billing_month" label="账单月份" width="120" /><el-table-column label="项目金额" min-width="170"><template #default="{row}">{{money(row.billing_totals)}}</template></el-table-column></el-table><template #footer><el-button @click="detail=null">关闭</el-button></template></DraggableFormDialog>
</template>
<script setup>
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import api from '@/api'
import {matchesSearchFields} from '@/utils/searchMatching'
import {translationSettlementModeLabels as modes} from '@/utils/settlementModes'
import {quotationLineCents,quotationMoney} from '@/utils/quotation'
import {getLocalizedErrorMessage} from '@/utils/errorMessages'
import {useDialogFieldSearch} from '@/composables/useDialogFieldSearch'
import DialogFieldSearchHeader from './DialogFieldSearchHeader.vue'
const props=defineProps({modelValue:Boolean,module:{type:String,default:'interpretation'},query:{type:Object,default:()=>({})}}),emit=defineEmits(['update:modelValue'])
const body=ref(),loading=ref(false),error=ref(''),rows=ref([]),detail=ref(null),tab=ref('audit'),filters=reactive({keyword:'',months:[],issue:'',mode:''})
const label=computed(()=>({interpretation:'口译',annotation:'标注',recruitment:'招聘'}[props.module]))
const {fieldSearchRef,fieldSearchKeyword,fetchFieldSuggestions,locateDialogField,clearFieldSearch}=useDialogFieldSearch(body)
const issues=[{value:'quantity',label:'工作量未填写'},{value:'price',label:'单价未填写'},{value:'invoice',label:'需发票但未开'},{value:'invoice_required',label:'需要发票'},{value:'unpaid',label:'尚未付全款'},{value:'fixed',label:'固定收费'},{value:'workload',label:'按工作量计费'}]
const visible=computed(()=>rows.value.filter(row=>{const setting=row.payload?.settlement||{},rates=row.payload?.rates||[];if(filters.months?.length&&!filters.months.includes(row.billing_month)||filters.mode&&row.settlement_mode!==filters.mode||!matchesSearchFields([row.order_no,row.project_name,row.client_name,row.client_short_name],filters.keyword))return false;return !filters.issue||({quantity:!rates.length||rates.some(item=>item.quantity==null),price:!rates.length||rates.some(item=>item.amount==null),invoice:setting.invoice_required&&row.payload.invoice?.invoice_status!=='issued',invoice_required:setting.invoice_required,unpaid:setting.payment_status!=='full',fixed:setting.pricing_mode==='fixed',workload:setting.pricing_mode!=='fixed'}[filters.issue])}))
const groups=computed(()=>{const result=new Map();for(const row of visible.value){const mode=row.settlement_mode;const key=['monthly','sub_client'].includes(mode)?[row.client_id,mode,mode==='sub_client'?row.sub_client_id:'',row.billing_month,row.payload.settlement.period_number].join(':'):row.id;if(!result.has(key))result.set(key,{client_id:row.client_id,client_name:row.client_name||row.client_short_name,name:['monthly','sub_client'].includes(mode)?`${row.billing_month} · ${modes[mode]}`:row.project_name,mode,items:[]});result.get(key).items.push(row)}return [...result.values()]})
function sum(items,key){const result={};for(const row of items)for(const [currency,value] of Object.entries(row[key]||{})){const cents=quotationLineCents({quantity:1,unit_price:value},6);if(cents!=null)result[currency]=(result[currency]||0n)+cents}return Object.fromEntries(Object.entries(result).map(([key,value])=>[key,quotationMoney(value)]))}
const money=value=>Object.entries(value||{}).map(([code,amount])=>code+' '+amount).join(' / ')||'待填写'
let controller
async function load(){controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{rows.value=(await api.get(`/business-finance/${props.module}/ledger`,{params:props.query,signal:controller.signal})).items}catch(e){if(e.code!=='ERR_CANCELED')error.value=getLocalizedErrorMessage(e,'查账追账加载失败')}finally{loading.value=false}}
watch(()=>props.modelValue,open=>{if(open){clearFieldSearch();void load()}},{immediate:true});onBeforeUnmount(()=>controller?.abort())
</script>
<style>.business-finance-ledger{display:flex;flex-direction:column;max-height:90vh;overflow:hidden}.business-finance-ledger>.el-dialog__body{flex:1;min-height:0;overflow-y:auto}.business-finance-ledger>.el-dialog__header,.business-finance-ledger>.el-dialog__footer{flex:none}.business-finance-ledger>.el-dialog__footer{border-top:1px solid var(--el-border-color)}</style>
